// Helpers for SQL text generated by the domain (projection DDL, view compiler). The view compiler inlines literals
// (S1 caveat: custom plans per query) because the ordered SELECT runs inside snapshot_create() via EXECUTE.
// Every literal goes through these functions; identifiers are generated from UUIDs and integers only.

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function assertUuid(value: string): string {
  if (!UUID_RE.test(value)) throw new Error(`Not a UUID: ${value}`);
  return value.toLowerCase();
}

/** Quoted string literal (standard_conforming_strings = on, the default). */
export function strLit(value: string): string {
  if (value.includes('\u0000')) throw new Error('NUL in SQL literal');
  return `'${value.replaceAll("'", "''")}'`;
}

export function uuidLit(value: string): string {
  return `'${assertUuid(value)}'::uuid`;
}

export function numLit(value: number): string {
  if (!Number.isFinite(value)) throw new Error(`Not a finite number: ${value}`);
  return `${value}::numeric`;
}

/** Escapes LIKE wildcards so user text matches literally (escape character is the default backslash). */
export function likeEscape(value: string): string {
  return value.replace(/[\\%_]/g, (m) => `\\${m}`);
}

/** Projection table name for an entity definition (schema proj). */
export function projectionTableName(entityDefinitionId: string): string {
  return `p_${assertUuid(entityDefinitionId).replaceAll('-', '')}`;
}

export function projectionTableRef(tableName: string): string {
  if (!/^p_[0-9a-f]{32}$/.test(tableName)) throw new Error(`Bad projection table name: ${tableName}`);
  return `proj."${tableName}"`;
}
